package localchat;
import javax.swing.*;import java.awt.*;import java.awt.image.BufferedImage;import java.nio.file.*;import java.util.*;import java.util.List;
/** Semantic icon colours and actual Swing timer, no native input or provider calls. */
public final class StatusActivityTest {
 static int checks;static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 static double channel(int value){double c=value/255.0;return c<=.04045?c/12.92:Math.pow((c+.055)/1.055,2.4);}
 static double light(Color c){return .2126*channel(c.getRed())+.7152*channel(c.getGreen())+.0722*channel(c.getBlue());}
 static double contrast(Color a,Color b){return (Math.max(light(a),light(b))+.05)/(Math.min(light(a),light(b))+.05);}
 static BufferedImage paint(Icon icon,JComponent host){BufferedImage image=new BufferedImage(20,20,BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();g.setColor(host.getBackground());g.fillRect(0,0,20,20);icon.paintIcon(host,g,3,3);g.dispose();return image;}
 public static void main(String[] args)throws Exception{
  Path home=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"run-");AgentActivityButton[] button={null};AgentPanel[] panel={null};Color[] before={null};
  FeatureTest.edt(()->{
   for(boolean dark:new boolean[]{false,true}){Color background=new Color(dark?0x1B1F26:0xFFFFFF);JLabel host=new JLabel();host.setBackground(background);host.setForeground(Color.GRAY);Set<Integer> distinct=new HashSet<>();for(String state:ProjectStatus.VALUES){Color tint=StatusColors.color(state,dark);distinct.add(tint.getRGB());check(contrast(tint,background)>=3,"icon contrast "+state+dark);BufferedImage image=paint(ProjectStatus.icon(state),host);boolean found=false;for(int x=0;x<20;x++)for(int y=0;y<20;y++)if(image.getRGB(x,y)==tint.getRGB())found=true;check(found,"project icon paints semantic hue "+state+dark);javax.imageio.ImageIO.write(image,"png",home.resolve(state+"-"+(dark?"dark":"light")+".png").toFile());}check(distinct.size()==5,"five distinct project colours "+dark);}
   button[0]=new AgentActivityButton(){@Override public boolean isShowing(){return true;}};button[0].setBackground(new Color(0x1B1F26));button[0].setSize(29,27);panel[0]=new AgentPanel(()->{},()->{});panel[0].onChange(()->button[0].activity(panel[0].runningCount(),panel[0].waitingCount(),panel[0].summaryState()));check(!button[0].active()&&!button[0].animating(),"idle chat does not animate");panel[0].queued("live-1","First","scope","model");check(!button[0].active(),"rows without a live parent do not animate");panel[0].busy(true);check(button[0].active()&&button[0].waiting()==1&&button[0].running()==0&&button[0].animating(),"queued actual child starts pulse with accurate waiting count");panel[0].progress("live-1","tool:read_file");panel[0].queued("live-2","Second","scope","model");check(button[0].running()==1&&button[0].waiting()==1,"running and queued children are counted separately");panel[0].setVisible(false);check(button[0].active(),"hidden panel retains live toolbar activity");before[0]=button[0].getForeground();
  });
  Thread.sleep(310);FeatureTest.edt(()->{check(!button[0].getForeground().equals(before[0]),"real Swing timer changes pulse phase without model calls");panel[0].busy(false);check(!button[0].active()&&!button[0].animating(),"parent Stop stops pulse even before archival refresh");panel[0].restore(AgentPanelTest.history(AgentPanelTest.result()));check(!button[0].active()&&panel[0].summaryState().equals("partial"),"historical terminal result stays static with correct colour");var pending=List.of(ChatClient.Message.assistant("",List.of(new ChatClient.ToolCall("old","run_agents",Json.obj("tasks",List.of(Json.obj("title","Old","task","scope"))))),"fixture"));panel[0].restore(pending);panel[0].busy(true);check(!button[0].active()&&!button[0].animating(),"archived unconfirmed tasks do not animate during another parent turn");panel[0].restore(List.of());check(!button[0].active()&&panel[0].summaryState().equals("draft"),"new chat clears counts and colour");for(String lang:I18n.CODES){I18n.setLanguage(lang);button[0].activity(2,1,"running");check(button[0].getToolTipText().equals(I18n.text("Panou agenti: {0} in lucru, {1} in asteptare",2,1)),"localized activity tooltip "+lang);button[0].activity(0,0,"done");check(!button[0].animating(),"terminal state stops timer "+lang);}button[0].activity(1,0,"running");button[0].disposeActivity();check(!button[0].animating(),"window disposal stops timer");});
  try(var server=new FeatureTest.Server()){FeatureTest.edt(()->{LocalChat app=AttachmentTest.window(home.resolve("app"),server.url());AttachmentTest.state(app).projectStatus="in_progress";FeatureTest.call(app,"setBusy",new Class<?>[]{boolean.class},true);FeatureTest.call(app,"refreshDashboard",new Class<?>[]{});JButton status=FeatureTest.field(app,"projectStatusButton");check(status.getIcon()==status.getDisabledIcon(),"busy toolbar retains coloured status icon instead of generated grayscale");AgentPanel agents=FeatureTest.field(app,"agentPanel");AgentActivityButton control=FeatureTest.field(app,"agentsButton");agents.queued("current","Current","scope","model");agents.progress("current","running");check(control.running()==1&&control.active(),"actual app agent callback drives toolbar indicator");for(String state:ProjectStatus.VALUES){var fixture=new Conversations.State();fixture.title=ProjectStatus.label(state);fixture.projectStatus=state;Conversations.save(Conversations.newFile(home.resolve("app/conversatii")),home.resolve("app").toString(),List.of(),fixture);}FeatureTest.call(app,"refreshSessions",new Class<?>[]{});app.setSize(1450,950);app.addNotify();app.validate();FeatureTest.call(app,"setAgentPaneVisible",new Class<?>[]{boolean.class},true);for(int theme=0;theme<2;theme++){((JComboBox<?>)FeatureTest.field(app,"themeBox")).setSelectedIndex(theme);app.validate();BufferedImage screenshot=new BufferedImage(app.getWidth(),app.getHeight(),BufferedImage.TYPE_INT_RGB);Graphics2D graphics=screenshot.createGraphics();app.getRootPane().printAll(graphics);graphics.dispose();javax.imageio.ImageIO.write(screenshot,"png",home.resolve(theme==1?"status-agent-dark.png":"status-agent-light.png").toFile());check(control.active()&&control.running()==1,"theme switch preserves actual live count "+theme);}FeatureTest.call(app,"setBusy",new Class<?>[]{boolean.class},false);check(!control.active()&&!control.animating()&&server.requests.isEmpty(),"app Stop state halts activity with zero inference");app.dispose();});}finally{FeatureTest.edt(()->{for(Window w:Window.getWindows())w.dispose();});}
  System.out.println("PASS: "+checks+" status/activity checks; semantic colours, contrast, actual timer, live counts, Stop, history, themes and languages; native=false");System.exit(0);
 }
}
